    'clickjacking' => ['gruppe' => 'sicherheit', 'stufe' => 2, 'de' => 'Seite lässt sich nicht heimlich einbetten', 'en' => 'Site cannot be embedded secretly', 'info_de' => ['wie' => 'Der Check sucht die Anweisung, dass Ihre Seite nicht in fremde Seiten eingebettet werden darf (X-Frame-Options oder frame-ancestors).', 'warum' => 'Sonst kann eine fremde Seite Ihre Seite unsichtbar überlagern und Besucher zu Klicks verleiten, die sie nicht wollen.', 'tun' => 'Eine Zeile in der Server-Einstellung ergänzen.'], 'info_en' => ['wie' => 'The check looks for the instruction that your site may not be embedded in other sites (X-Frame-Options or frame-ancestors).', 'warum' => 'Otherwise a foreign site can overlay yours invisibly and trick visitors into clicks they did not intend.', 'tun' => 'Add one line to the server settings.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
