    'permissions' => ['gruppe' => 'sicherheit', 'stufe' => 3, 'de' => 'Kamera, Mikrofon und Standort gesperrt', 'en' => 'Camera, microphone and location locked', 'info_de' => ['wie' => 'Der Check sucht eine „Permissions-Policy“, die nicht benötigte Funktionen wie Kamera, Mikrofon oder Standort abschaltet.', 'warum' => 'Eingebettete fremde Inhalte können diese Funktionen dann nicht heimlich anfragen.', 'tun' => 'Eine Zeile in der Server-Einstellung ergänzen.'], 'info_en' => ['wie' => 'The check looks for a “Permissions-Policy” that switches off unneeded features such as camera, microphone or location.', 'warum' => 'Embedded third-party content can then not secretly request these features.', 'tun' => 'Add one line to the server settings.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'versionen' => ['gruppe' => 'sicherheit', 'stufe' => 3, 'de' => 'Keine Softwareversionen sichtbar', 'en' => 'No software versions visible', 'info_de' => ['wie' => 'Der Check schaut, ob Ihr Server oder Ihr System Versionsnummern verrät, etwa „Apache 2.4“ oder „WordPress 6.1“.', 'warum' => 'Versionsnummern zeigen Angreifern, welche bekannten Lücken sie ausprobieren können.', 'tun' => 'Die Anzeige der Versionen in Server und System abschalten.'], 'info_en' => ['wie' => 'The check tests whether your server or system reveals version numbers such as “Apache 2.4” or “WordPress 6.1”.', 'warum' => 'Version numbers show attackers which known flaws they can try.', 'tun' => 'Switch off the version display in server and system.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'securitytxt' => ['gruppe' => 'sicherheit', 'stufe' => 3, 'de' => 'Kontakt für Sicherheitshinweise', 'en' => 'Contact for security reports', 'info_de' => ['wie' => 'Der Check prüft, ob es die Datei „/.well-known/security.txt“ gibt, in der steht, wohin man Sicherheitslücken melden kann.', 'warum' => 'Wer eine Lücke findet, weiß dann, wen er informieren kann, bevor jemand sie ausnutzt.', 'tun' => 'Eine kurze Textdatei mit E-Mail-Adresse und Ablaufdatum anlegen.'], 'info_en' => ['wie' => 'The check tests whether the file “/.well-known/security.txt” exists, stating where security flaws can be reported.', 'warum' => 'Anyone who finds a flaw then knows whom to tell before someone exploits it.', 'tun' => 'Create a short text file with an email address and expiry date.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'cookies_sicher' => ['gruppe' => 'sicherheit', 'stufe' => 3, 'de' => 'Cookies sind gegen Mitlesen geschützt', 'en' => 'Cookies are protected against snooping', 'info_de' => ['wie' => 'Setzt Ihre Startseite Cookies, prüft der Check, ob sie nur verschlüsselt übertragen werden („Secure“) und für Skripte gesperrt sind („HttpOnly“).', 'warum' => 'Ungeschützte Cookies, etwa für Logins, lassen sich leichter stehlen.', 'tun' => 'Die Cookie-Einstellungen im System oder auf dem Server anpassen.'], 'info_en' => ['wie' => 'If your homepage sets cookies, the check tests whether they are only sent encrypted (“Secure”) and locked for scripts (“HttpOnly”).', 'warum' => 'Unprotected cookies, for example for logins, are easier to steal.', 'tun' => 'Adjust the cookie settings in the system or on the server.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'system_aktuell' => ['gruppe' => 'sicherheit', 'stufe' => 3, 'de' => 'Kein veraltetes System erkennbar', 'en' => 'No outdated system visible', 'info_de' => ['wie' => 'Verrät Ihre Seite ein Baukasten- oder CMS-System mit Version (z. B. WordPress), vergleicht der Check die Version mit dem aktuellen Stand.', 'warum' => 'Veraltete Systeme sind das häufigste Einfallstor für gehackte Websites.', 'tun' => 'System, Erweiterungen und Designs aktualisieren und regelmäßig pflegen.'], 'info_en' => ['wie' => 'If your site reveals a website builder or CMS with a version (e.g. WordPress), the check compares the version with the current release.', 'warum' => 'Outdated systems are the most common way websites get hacked.', 'tun' => 'Update the system, plugins and themes and keep them maintained.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'impressum' => ['gruppe' => 'recht', 'stufe' => 1, 'de' => 'Impressum mit einem Klick erreichbar', 'en' => 'Legal notice one click away', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite einen Link „Impressum“ und ruft die Seite auf.', 'warum' => 'Für geschäftliche Websites in Deutschland ist das Impressum Pflicht. Fehlt es oder ist es versteckt, drohen Abmahnungen.', 'tun' => 'Ein Impressum anlegen und von jeder Seite aus verlinken, am besten in der Fußzeile.'], 'info_en' => ['wie' => 'The check looks for a “legal notice” (Impressum) link on the homepage and opens the page.', 'warum' => 'For business websites in Germany the legal notice is mandatory. If it is missing or hidden, legal warnings are likely.', 'tun' => 'Create a legal notice and link it from every page, ideally in the footer.'], 'leistung' => 'recht', 'leistung_de' => 'Die technische Umsetzung übernehme ich. Den Inhalt der Rechtstexte prüft am besten ein Rechtstext-Dienst oder eine Anwältin.', 'leistung_en' => 'I handle the technical side. The content of legal texts is best checked by a legal-text service or a lawyer.', 'leistung_name_de' => 'Rechtstexte technisch umsetzen', 'leistung_name_en' => 'Implementing legal texts'],
    'datenschutz' => ['gruppe' => 'recht', 'stufe' => 1, 'de' => 'Datenschutzerklärung erreichbar', 'en' => 'Privacy policy reachable', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite einen Link „Datenschutz“ und ruft die Seite auf.', 'warum' => 'Jede Website verarbeitet Daten, schon durch den Server. Die DSGVO verlangt deshalb eine Datenschutzerklärung.', 'tun' => 'Eine Datenschutzerklärung erstellen, die zu den tatsächlich genutzten Diensten passt, und überall verlinken.'], 'info_en' => ['wie' => 'The check looks for a “privacy” link on the homepage and opens the page.', 'warum' => 'Every website processes data, if only through the server. The GDPR therefore requires a privacy policy.', 'tun' => 'Create a privacy policy that matches the services actually used and link it everywhere.'], 'leistung' => 'recht', 'leistung_de' => 'Die technische Umsetzung übernehme ich. Den Inhalt der Rechtstexte prüft am besten ein Rechtstext-Dienst oder eine Anwältin.', 'leistung_en' => 'I handle the technical side. The content of legal texts is best checked by a legal-text service or a lawyer.', 'leistung_name_de' => 'Rechtstexte technisch umsetzen', 'leistung_name_en' => 'Implementing legal texts'],
    'dritte' => ['gruppe' => 'recht', 'stufe' => 1, 'de' => 'Keine fremden Dienste ohne Zustimmung', 'en' => 'No third-party services without consent', 'info_de' => ['wie' => 'Der Check schaut, welche fremden Dienste schon beim ersten Aufruf geladen werden, zum Beispiel Google Fonts, Google Analytics, Facebook, YouTube oder Google Maps.', 'warum' => 'Diese Dienste erfahren die IP-Adresse Ihrer Besucher. Ohne Zustimmung ist das unzulässig, dafür gab es schon Abmahnwellen.', 'tun' => 'Schriften auf dem eigenen Server ablegen und Karten, Videos und Statistik erst nach Zustimmung laden.'], 'info_en' => ['wie' => 'The check tests which third-party services load on the very first visit, for example Google Fonts, Google Analytics, Facebook, YouTube or Google Maps.', 'warum' => 'These services learn your visitors’ IP addresses. Without consent this is not allowed, and it has already led to waves of legal warnings.', 'tun' => 'Host fonts on your own server and load maps, videos and statistics only after consent.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'einwilligung' => ['gruppe' => 'recht', 'stufe' => 2, 'de' => 'Zustimmung vor Statistik und Werbung', 'en' => 'Consent before statistics and ads', 'info_de' => ['wie' => 'Findet der Check Statistik- oder Werbedienste, prüft er, ob ein Zustimmungs-Banner (Cookie-Banner) eingebunden ist.', 'warum' => 'Statistik und Werbung brauchen eine vorherige Zustimmung. Fehlt sie, drohen Bußgelder.', 'tun' => 'Ein Zustimmungs-Banner einrichten oder auf Statistik ohne Cookies umsteigen.'], 'info_en' => ['wie' => 'If the check finds statistics or advertising services, it checks whether a consent (cookie) banner is in place.', 'warum' => 'Statistics and advertising need prior consent. Without it, fines are possible.', 'tun' => 'Set up a consent banner or switch to cookie-free statistics.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'impressum_inhalt' => ['gruppe' => 'recht', 'stufe' => 2, 'de' => 'Impressum enthält die Pflichtangaben', 'en' => 'Legal notice has the required details', 'info_de' => ['wie' => 'Im Impressum sucht der Check eine Anschrift mit Postleitzahl und eine E-Mail-Adresse.', 'warum' => 'Ein Impressum ohne Anschrift oder schnellen Kontaktweg gilt als unvollständig und kann abgemahnt werden.', 'tun' => 'Name, vollständige Anschrift, E-Mail und, falls vorhanden, Registereintrag und Umsatzsteuer-ID ergänzen.'], 'info_en' => ['wie' => 'In the legal notice the check looks for an address with postcode and an email address.', 'warum' => 'A legal notice without an address or quick way of contact counts as incomplete and can be challenged.', 'tun' => 'Add name, full address, email and, if applicable, register entry and VAT ID.'], 'leistung' => 'recht', 'leistung_de' => 'Die technische Umsetzung übernehme ich. Den Inhalt der Rechtstexte prüft am besten ein Rechtstext-Dienst oder eine Anwältin.', 'leistung_en' => 'I handle the technical side. The content of legal texts is best checked by a legal-text service or a lawyer.', 'leistung_name_de' => 'Rechtstexte technisch umsetzen', 'leistung_name_en' => 'Implementing legal texts'],
    'cookies' => ['gruppe' => 'recht', 'stufe' => 2, 'de' => 'Keine Werbe-Cookies vor der Zustimmung', 'en' => 'No advertising cookies before consent', 'info_de' => ['wie' => 'Der Check schaut, welche Cookies Ihre Startseite sofort setzt, und sucht bekannte Statistik- und Werbe-Cookies (z. B. von Google oder Facebook).', 'warum' => 'Solche Cookies dürfen erst nach einer Zustimmung gesetzt werden.', 'tun' => 'Die Dienste so einstellen, dass sie erst nach der Zustimmung starten.'], 'info_en' => ['wie' => 'The check tests which cookies your homepage sets immediately and looks for known statistics and advertising cookies (e.g. from Google or Facebook).', 'warum' => 'Such cookies may only be set after consent.', 'tun' => 'Configure the services to start only after consent.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'formulare' => ['gruppe' => 'recht', 'stufe' => 2, 'de' => 'Formulare senden verschlüsselt', 'en' => 'Forms send encrypted', 'info_de' => ['wie' => 'Der Check prüft bei allen Formularen auf der Startseite und der Kontaktseite, wohin sie Eingaben schicken.', 'warum' => 'Namen, E-Mail-Adressen und Nachrichten dürfen nur verschlüsselt übertragen werden.', 'tun' => 'Die Formular-Adresse auf https:// umstellen.'], 'info_en' => ['wie' => 'For all forms on the homepage and contact page the check tests where they send entries.', 'warum' => 'Names, email addresses and messages may only be transmitted encrypted.', 'tun' => 'Switch the form address to https://.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'impressum_aktuell' => ['gruppe' => 'recht', 'stufe' => 3, 'de' => 'Rechtstexte nennen aktuelle Gesetze', 'en' => 'Legal texts cite current laws', 'info_de' => ['wie' => 'Der Check liest das Impressum und schaut, ob noch das 2024 abgelöste Telemediengesetz (TMG) statt des Digitale-Dienste-Gesetzes (DDG) genannt wird.', 'warum' => 'Veraltete Angaben wirken ungepflegt und deuten darauf hin, dass auch andere Texte nicht mehr stimmen.', 'tun' => 'Den Verweis auf § 5 DDG aktualisieren und die Rechtstexte insgesamt prüfen.'], 'info_en' => ['wie' => 'The check reads the legal notice and checks whether it still cites the Telemedia Act (TMG), replaced in 2024, instead of the Digital Services Act (DDG).', 'warum' => 'Outdated references look neglected and suggest other texts may no longer be correct either.', 'tun' => 'Update the reference to § 5 DDG and review the legal texts as a whole.'], 'leistung' => 'recht', 'leistung_de' => 'Die technische Umsetzung übernehme ich. Den Inhalt der Rechtstexte prüft am besten ein Rechtstext-Dienst oder eine Anwältin.', 'leistung_en' => 'I handle the technical side. The content of legal texts is best checked by a legal-text service or a lawyer.', 'leistung_name_de' => 'Rechtstexte technisch umsetzen', 'leistung_name_en' => 'Implementing legal texts'],
    'formular_hinweis' => ['gruppe' => 'recht', 'stufe' => 3, 'de' => 'Formular mit Datenschutzhinweis', 'en' => 'Form with privacy notice', 'info_de' => ['wie' => 'Gibt es ein Formular, sucht der Check daneben einen Hinweis oder ein Häkchen zum Datenschutz.', 'warum' => 'Wer Daten eingibt, muss erfahren, was damit passiert. Das schafft auch Vertrauen.', 'tun' => 'Einen kurzen Satz mit Link zur Datenschutzerklärung über dem Absende-Knopf ergänzen.'], 'info_en' => ['wie' => 'If there is a form, the check looks for a privacy notice or checkbox next to it.', 'warum' => 'Anyone entering data must learn what happens to it. That also builds trust.', 'tun' => 'Add a short sentence linking to the privacy policy above the send button.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'rechtstexte_ueberall' => ['gruppe' => 'recht', 'stufe' => 3, 'de' => 'Rechtstexte auf jeder Seite verlinkt', 'en' => 'Legal texts linked on every page', 'info_de' => ['wie' => 'Der Check öffnet mehrere Unterseiten und prüft, ob dort ebenfalls Impressum und Datenschutz verlinkt sind.', 'warum' => 'Das Impressum muss von jeder Seite aus „leicht erkennbar und unmittelbar erreichbar“ sein, nicht nur von der Startseite.', 'tun' => 'Beide Links in die gemeinsame Fußzeile aller Seiten setzen.'], 'info_en' => ['wie' => 'The check opens several subpages and checks whether the legal notice and privacy policy are linked there too.', 'warum' => 'The legal notice must be “easily recognisable and directly accessible” from every page, not only the homepage.', 'tun' => 'Put both links in the shared footer of all pages.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'barrierefreiheit' => ['gruppe' => 'recht', 'stufe' => 3, 'de' => 'Erklärung zur Barrierefreiheit (bei Shops)', 'en' => 'Accessibility statement (for shops)', 'info_de' => ['wie' => 'Erkennt der Check einen Online-Shop oder eine Buchung mit Bezahlung, sucht er eine Erklärung zur Barrierefreiheit.', 'warum' => 'Seit Juni 2025 verlangt das Barrierefreiheitsstärkungsgesetz das für viele Online-Shops und Buchungen an Verbraucher.', 'tun' => 'Prüfen, ob das Gesetz für Sie gilt, die Seite barriereärmer machen und eine Erklärung veröffentlichen.'], 'info_en' => ['wie' => 'If the check detects an online shop or paid booking, it looks for an accessibility statement.', 'warum' => 'Since June 2025, the German Accessibility Act requires this for many online shops and consumer bookings.', 'tun' => 'Check whether the law applies to you, make the site more accessible and publish a statement.'], 'leistung' => 'recht', 'leistung_de' => 'Die technische Umsetzung übernehme ich. Den Inhalt der Rechtstexte prüft am besten ein Rechtstext-Dienst oder eine Anwältin.', 'leistung_en' => 'I handle the technical side. The content of legal texts is best checked by a legal-text service or a lawyer.', 'leistung_name_de' => 'Rechtstexte technisch umsetzen', 'leistung_name_en' => 'Implementing legal texts'],
    'eine_adresse' => ['gruppe' => 'adresse', 'stufe' => 1, 'de' => 'Eine eindeutige Adresse, mit und ohne „www“', 'en' => 'One clear address, with and without “www”', 'info_de' => ['wie' => 'Der Check ruft Ihre Adresse mit und ohne „www“ auf und prüft, ob beide auf dieselbe Seite führen und nicht auf eine fremde Domain.', 'warum' => 'Zwei getrennte Versionen verwirren Google und Besucher. Landet die Seite auf einer anderen Domain, wirkt das unseriös.', 'tun' => 'Eine Variante festlegen und die andere dauerhaft dorthin weiterleiten.'], 'info_en' => ['wie' => 'The check opens your address with and without “www” and checks whether both lead to the same site and not to a foreign domain.', 'warum' => 'Two separate versions confuse Google and visitors. If the site ends up on another domain, it looks dubious.', 'tun' => 'Choose one variant and permanently redirect the other to it.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'kette' => ['gruppe' => 'adresse', 'stufe' => 2, 'de' => 'Keine Umwege bis zur Startseite', 'en' => 'No detours to the homepage', 'info_de' => ['wie' => 'Der Check zählt, über wie viele Weiterleitungen Ihre Startseite erreicht wird.', 'warum' => 'Jeder Umweg kostet Ladezeit. Mehr als zwei deuten auf eine unsaubere Einrichtung hin.', 'tun' => 'Die Weiterleitungen so einstellen, dass jede Adresse direkt zum Ziel führt.'], 'info_en' => ['wie' => 'The check counts how many redirects it takes to reach your homepage.', 'warum' => 'Every detour costs loading time. More than two point to a messy setup.', 'tun' => 'Set up the redirects so every address leads straight to the target.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'fremde_adressen' => ['gruppe' => 'adresse', 'stufe' => 2, 'de' => 'Keine fremden oder Test-Adressen', 'en' => 'No foreign or test addresses', 'info_de' => ['wie' => 'Der Check sucht in Weiterleitungen, Links und unsichtbaren Angaben nach Baukasten-, Test- oder IP-Adressen (z. B. „…wixsite.com“ oder „staging.“).', 'warum' => 'Solche Adressen wirken unprofessionell und können Besucher oder Google an falsche Orte schicken.', 'tun' => 'Alle Verweise auf die eigene Domain umstellen und alte Test-Adressen abschalten.'], 'info_en' => ['wie' => 'The check looks in redirects, links and hidden tags for site-builder, test or IP addresses (e.g. “…wixsite.com” or “staging.”).', 'warum' => 'Such addresses look unprofessional and can send visitors or Google to the wrong place.', 'tun' => 'Point all references to your own domain and switch off old test addresses.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'fehlerseite' => ['gruppe' => 'adresse', 'stufe' => 2, 'de' => 'Fehlerseite meldet sich richtig', 'en' => 'Error page reports correctly', 'info_de' => ['wie' => 'Der Check ruft eine Adresse auf, die es nicht gibt, und prüft, ob der Server „nicht gefunden“ (404) meldet.', 'warum' => 'Meldet der Server „alles in Ordnung“, nimmt Google leere Seiten in den Index auf und Ihre echten Seiten verlieren an Gewicht.', 'tun' => 'Eine echte 404-Fehlerseite einrichten.'], 'info_en' => ['wie' => 'The check opens an address that does not exist and checks whether the server reports “not found” (404).', 'warum' => 'If the server reports “all fine”, Google indexes empty pages and your real pages lose weight.', 'tun' => 'Set up a real 404 error page.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'links' => ['gruppe' => 'adresse', 'stufe' => 2, 'de' => 'Keine kaputten Links', 'en' => 'No broken links', 'info_de' => ['wie' => 'Der Check ruft die Links auf Ihrer Startseite auf (im ausführlichen Check bis zu 30) und notiert alle, die ins Leere führen.', 'warum' => 'Kaputte Links ärgern Besucher und lassen die Seite ungepflegt wirken, auch bei Google.', 'tun' => 'Die betroffenen Links korrigieren oder entfernen.'], 'info_en' => ['wie' => 'The check opens the links on your homepage (up to 30 in the detailed check) and notes any that lead nowhere.', 'warum' => 'Broken links annoy visitors and make the site look neglected, also to Google.', 'tun' => 'Correct or remove the affected links.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'fehlerseite_hilfe' => ['gruppe' => 'adresse', 'stufe' => 3, 'de' => 'Fehlerseite hilft weiter', 'en' => 'Error page helps visitors on', 'info_de' => ['wie' => 'Der Check schaut, ob Ihre Fehlerseite einen Link zurück zur Startseite oder ins Menü anbietet.', 'warum' => 'Wer auf einem alten Link landet, soll nicht in einer Sackgasse stehen, sondern weiterfinden.', 'tun' => 'Die Fehlerseite mit Menü, Suche oder Link zur Startseite gestalten.'], 'info_en' => ['wie' => 'The check tests whether your error page offers a link back to the homepage or the menu.', 'warum' => 'Anyone landing on an old link should not hit a dead end but find their way on.', 'tun' => 'Design the error page with a menu, search or a link to the homepage.'], 'leistung' => 'neubau', 'leistung_de' => 'Bei einer neuen Website in 7 Tagen ist das von Anfang an erledigt.', 'leistung_en' => 'With a new website in 7 days, this is done from the start.', 'leistung_name_de' => 'Neue Website in 7 Tagen', 'leistung_name_en' => 'New website in 7 days'],
    'ipv6' => ['gruppe' => 'adresse', 'stufe' => 3, 'de' => 'Auch über das neue Internet-Protokoll erreichbar', 'en' => 'Also reachable via the new internet protocol', 'info_de' => ['wie' => 'Der Check prüft, ob Ihre Domain eine IPv6-Adresse hat (Eintrag „AAAA“).', 'warum' => 'Viele Mobilfunknetze arbeiten mit IPv6. Mit passendem Eintrag lädt Ihre Seite dort ohne Umweg.', 'tun' => 'IPv6 beim Hoster einschalten.'], 'info_en' => ['wie' => 'The check tests whether your domain has an IPv6 address (“AAAA” record).', 'warum' => 'Many mobile networks use IPv6. With a matching record your site loads there directly.', 'tun' => 'Switch on IPv6 at your host.'], 'leistung' => 'hoster', 'leistung_de' => 'Das kläre ich mit Ihrem Hoster oder ziehe die Website auf ein schnelleres Hosting um.', 'leistung_en' => 'I sort this out with your host or move the site to faster hosting.', 'leistung_name_de' => 'Hosting und Server', 'leistung_name_en' => 'Hosting and server'],
    'links_http' => ['gruppe' => 'adresse', 'stufe' => 3, 'de' => 'Links führen auf sichere Seiten', 'en' => 'Links point to secure pages', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite Links, die noch mit http:// statt https:// beginnen.', 'warum' => 'Solche Links schicken Besucher auf unsichere Seiten oder machen einen Umweg.', 'tun' => 'Die Links auf https:// umstellen.'], 'info_en' => ['wie' => 'The check looks on the homepage for links still starting with http:// instead of https://.', 'warum' => 'Such links send visitors to insecure pages or take a detour.', 'tun' => 'Switch the links to https://.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'nameserver' => ['gruppe' => 'adresse', 'stufe' => 3, 'de' => 'Domain ist ausfallsicher eingerichtet', 'en' => 'Domain is set up to be fail-safe', 'info_de' => ['wie' => 'Der Check zählt die Nameserver Ihrer Domain, also die Server, die Ihre Adresse ins Internet „übersetzen“.', 'warum' => 'Mit mindestens zwei Nameservern bleibt Ihre Seite erreichbar, auch wenn einer ausfällt.', 'tun' => 'Beim Domain-Anbieter einen zweiten Nameserver eintragen.'], 'info_en' => ['wie' => 'The check counts your domain’s name servers, the servers that “translate” your address on the internet.', 'warum' => 'With at least two name servers your site stays reachable even if one fails.', 'tun' => 'Add a second name server at your domain provider.'], 'leistung' => 'hoster', 'leistung_de' => 'Das kläre ich mit Ihrem Hoster oder ziehe die Website auf ein schnelleres Hosting um.', 'leistung_en' => 'I sort this out with your host or move the site to faster hosting.', 'leistung_name_de' => 'Hosting und Server', 'leistung_name_en' => 'Hosting and server'],
    'caa' => ['gruppe' => 'adresse', 'stufe' => 3, 'de' => 'Festgelegt, wer Zertifikate ausstellen darf', 'en' => 'Defined who may issue certificates', 'info_de' => ['wie' => 'Der Check sucht einen CAA-Eintrag in Ihrer Domain. Er legt fest, welche Stellen Zertifikate für Ihre Adresse ausstellen dürfen.', 'warum' => 'So kann sich niemand bei einer anderen Stelle ein Zertifikat für Ihre Adresse erschleichen.', 'tun' => 'Einen CAA-Eintrag für Ihren Zertifikatsanbieter anlegen.'], 'info_en' => ['wie' => 'The check looks for a CAA record in your domain. It defines which authorities may issue certificates for your address.', 'warum' => 'This stops anyone from obtaining a certificate for your address from another authority.', 'tun' => 'Create a CAA record for your certificate provider.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'viewport' => ['gruppe' => 'mobil', 'stufe' => 1, 'de' => 'Für Handys eingerichtet', 'en' => 'Set up for phones', 'info_de' => ['wie' => 'Der Check sucht die Angabe „viewport“, mit der sich die Seite an die Bildschirmbreite des Handys anpasst.', 'warum' => 'Über die Hälfte der Besucher kommt mit dem Handy. Ohne diese Angabe erscheint eine winzige Desktop-Seite.', 'tun' => 'Die Seite auf ein Layout umstellen, das sich jedem Bildschirm anpasst.'], 'info_en' => ['wie' => 'The check looks for the “viewport” setting that makes the site adapt to the phone’s screen width.', 'warum' => 'Over half of visitors use a phone. Without this setting a tiny desktop page appears.', 'tun' => 'Switch the site to a layout that adapts to every screen.'], 'leistung' => 'neubau', 'leistung_de' => 'Bei einer neuen Website in 7 Tagen ist das von Anfang an erledigt.', 'leistung_en' => 'With a new website in 7 days, this is done from the start.', 'leistung_name_de' => 'Neue Website in 7 Tagen', 'leistung_name_en' => 'New website in 7 days'],
    'zoom' => ['gruppe' => 'mobil', 'stufe' => 2, 'de' => 'Vergrößern ist erlaubt', 'en' => 'Zooming is allowed', 'info_de' => ['wie' => 'Der Check prüft, ob die Seite das Vergrößern mit zwei Fingern sperrt.', 'warum' => 'Für Menschen, die schlecht sehen, ist gesperrtes Zoomen eine echte Hürde.', 'tun' => 'Die Sperre in der viewport-Angabe entfernen.'], 'info_en' => ['wie' => 'The check tests whether the site blocks pinch-to-zoom.', 'warum' => 'For people with poor eyesight, blocked zoom is a real barrier.', 'tun' => 'Remove the block from the viewport setting.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'bildmasse' => ['gruppe' => 'mobil', 'stufe' => 2, 'de' => 'Nichts verrutscht beim Laden', 'en' => 'Nothing jumps while loading', 'info_de' => ['wie' => 'Der Check prüft, ob die Bilder auf der Startseite feste Maße (Breite und Höhe) haben.', 'warum' => 'Ohne Maße springt der Text, während Bilder nachladen. Besucher tippen daneben, und Google wertet das ab.', 'tun' => 'Bei allen Bildern Breite und Höhe angeben.'], 'info_en' => ['wie' => 'The check tests whether the images on the homepage have fixed dimensions (width and height).', 'warum' => 'Without dimensions the text jumps while images load. Visitors tap the wrong thing and Google penalises it.', 'tun' => 'Set width and height on all images.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'starre_breiten' => ['gruppe' => 'mobil', 'stufe' => 2, 'de' => 'Nichts ragt über den Rand', 'en' => 'Nothing sticks out at the edge', 'info_de' => ['wie' => 'Der Check sucht Elemente mit fester Breite ab 600 Pixeln, etwa Tabellen oder Bilder, die auf dem Handy nicht hineinpassen.', 'warum' => 'Solche Elemente schieben die Seite zur Seite oder überlappen andere Inhalte.', 'tun' => 'Feste Breiten durch flexible ersetzen.'], 'info_en' => ['wie' => 'The check looks for elements with a fixed width of 600 pixels or more, such as tables or images that do not fit on a phone.', 'warum' => 'Such elements push the page sideways or overlap other content.', 'tun' => 'Replace fixed widths with flexible ones.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'favicon' => ['gruppe' => 'mobil', 'stufe' => 3, 'de' => 'Eigenes Symbol im Browser-Tab', 'en' => 'Own icon in the browser tab', 'info_de' => ['wie' => 'Der Check sucht ein Favicon, das kleine Symbol im Browser-Tab.', 'warum' => 'Es erscheint im Tab, in Lesezeichen und bei Google neben Ihrem Eintrag. Ohne Symbol wirkt die Seite unfertig.', 'tun' => 'Ein Symbol aus dem Logo erstellen und einbinden.'], 'info_en' => ['wie' => 'The check looks for a favicon, the small icon in the browser tab.', 'warum' => 'It appears in tabs, bookmarks and next to your Google listing. Without an icon the site looks unfinished.', 'tun' => 'Create an icon from your logo and add it.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'apple_icon' => ['gruppe' => 'mobil', 'stufe' => 3, 'de' => 'Symbol für den Handy-Startbildschirm', 'en' => 'Icon for the phone home screen', 'info_de' => ['wie' => 'Der Check sucht ein Symbol für den Startbildschirm (apple-touch-icon), das erscheint, wenn jemand Ihre Seite auf dem Handy ablegt.', 'warum' => 'Ohne Symbol zeigt das Handy nur einen Ausschnitt der Seite statt Ihres Logos.', 'tun' => 'Ein Symbol in 180 × 180 Pixeln einbinden.'], 'info_en' => ['wie' => 'The check looks for a home-screen icon (apple-touch-icon) that appears when someone saves your site on their phone.', 'warum' => 'Without it the phone shows only a screenshot of the page instead of your logo.', 'tun' => 'Add an icon at 180 × 180 pixels.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'manifest' => ['gruppe' => 'mobil', 'stufe' => 3, 'de' => 'Seite lässt sich wie eine App ablegen', 'en' => 'Site can be saved like an app', 'info_de' => ['wie' => 'Der Check sucht ein Web-App-Manifest, eine kleine Datei mit Name, Farben und Symbolen Ihrer Seite.', 'warum' => 'Damit sieht Ihre Seite auf dem Startbildschirm des Handys aus wie eine App.', 'tun' => 'Ein Manifest anlegen und verlinken.'], 'info_en' => ['wie' => 'The check looks for a web app manifest, a small file with your site’s name, colours and icons.', 'warum' => 'It makes your site look like an app on the phone’s home screen.', 'tun' => 'Create a manifest and link it.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'bilder_modern' => ['gruppe' => 'mobil', 'stufe' => 3, 'de' => 'Bilder sparsam geladen', 'en' => 'Images loaded efficiently', 'info_de' => ['wie' => 'Der Check schaut, ob Bilder in modernen Formaten (WebP, AVIF), in passenden Größen oder erst beim Scrollen geladen werden.', 'warum' => 'So lädt die Seite auf dem Handy oft doppelt so schnell und verbraucht weniger Datenvolumen.', 'tun' => 'Bilder umwandeln und „lazy loading“ einschalten.'], 'info_en' => ['wie' => 'The check tests whether images use modern formats (WebP, AVIF), suitable sizes or load only when scrolling.', 'warum' => 'This often makes the site load twice as fast on phones and use less data.', 'tun' => 'Convert images and switch on “lazy loading”.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'schrift' => ['gruppe' => 'mobil', 'stufe' => 3, 'de' => 'Keine winzige Schrift', 'en' => 'No tiny text', 'info_de' => ['wie' => 'Der Check sucht im HTML feste Schriftgrößen unter 12 Pixeln.', 'warum' => 'Zu kleine Schrift ist auf dem Handy kaum lesbar. Besucher müssen zoomen oder gehen.', 'tun' => 'Mindestens 14 bis 16 Pixel für Fließtext verwenden.'], 'info_en' => ['wie' => 'The check looks in the HTML for fixed font sizes below 12 pixels.', 'warum' => 'Text that is too small is hard to read on a phone. Visitors have to zoom or leave.', 'tun' => 'Use at least 14 to 16 pixels for body text.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'titel' => ['gruppe' => 'google', 'stufe' => 1, 'de' => 'Aussagekräftiger Seitentitel', 'en' => 'Meaningful page title', 'info_de' => ['wie' => 'Der Check liest den Seitentitel, also die blaue Zeile bei Google, und prüft Länge (15 bis 65 Zeichen) und ob er mehr sagt als „Startseite“.', 'warum' => 'Der Titel entscheidet, ob Ihre Seite bei Google gefunden und angeklickt wird.', 'tun' => 'Einen Titel mit Leistung und Ort formulieren, z. B. „Friseur in Karlsruhe – Salon Muster“.'], 'info_en' => ['wie' => 'The check reads the page title, the blue line on Google, and checks its length (15 to 65 characters) and whether it says more than “Home”.', 'warum' => 'The title decides whether your site is found and clicked on Google.', 'tun' => 'Write a title with service and location, e.g. “Hairdresser in Karlsruhe – Salon Muster”.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'indexierbar' => ['gruppe' => 'google', 'stufe' => 1, 'de' => 'Für Google freigegeben', 'en' => 'Open to Google', 'info_de' => ['wie' => 'Der Check prüft, ob die Startseite eine Sperre für Suchmaschinen enthält (noindex oder eine Sperre in der robots.txt).', 'warum' => 'Eine gesperrte Seite erscheint bei Google überhaupt nicht. Das passiert oft, wenn nach einem Neustart die Sperre vergessen wird.', 'tun' => 'Die Sperre entfernen und die Seite bei Google neu einreichen.'], 'info_en' => ['wie' => 'The check tests whether the homepage contains a block for search engines (noindex or a block in robots.txt).', 'warum' => 'A blocked site does not appear on Google at all. This often happens when the block is forgotten after a relaunch.', 'tun' => 'Remove the block and resubmit the site to Google.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'beschreibung' => ['gruppe' => 'google', 'stufe' => 2, 'de' => 'Beschreibung für Google', 'en' => 'Description for Google', 'info_de' => ['wie' => 'Der Check liest die Meta-Beschreibung, den grauen Text unter dem Titel bei Google, und prüft die Länge (50 bis 170 Zeichen).', 'warum' => 'Eine gute Beschreibung bringt mehr Klicks. Fehlt sie, nimmt Google irgendeinen Textschnipsel.', 'tun' => 'Für jede Seite eine eigene Beschreibung mit Nutzen und Ort schreiben.'], 'info_en' => ['wie' => 'The check reads the meta description, the grey text under the title on Google, and checks its length (50 to 170 characters).', 'warum' => 'A good description brings more clicks. Without it Google picks a random text snippet.', 'tun' => 'Write a description with benefit and location for each page.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'h1' => ['gruppe' => 'google', 'stufe' => 2, 'de' => 'Genau eine Hauptüberschrift', 'en' => 'Exactly one main heading', 'info_de' => ['wie' => 'Der Check zählt die Hauptüberschriften (H1) auf der Startseite.', 'warum' => 'Eine klare Hauptüberschrift zeigt Google und Vorlesehilfen, worum es geht.', 'tun' => 'Eine Hauptüberschrift festlegen, weitere als Zwischenüberschriften setzen.'], 'info_en' => ['wie' => 'The check counts the main headings (H1) on the homepage.', 'warum' => 'One clear main heading shows Google and screen readers what the page is about.', 'tun' => 'Define one main heading and turn others into subheadings.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'sitemap' => ['gruppe' => 'google', 'stufe' => 2, 'de' => 'Inhaltsverzeichnis für Google', 'en' => 'Table of contents for Google', 'info_de' => ['wie' => 'Der Check sucht eine Sitemap, ein Verzeichnis aller Seiten, unter den üblichen Adressen und in der robots.txt.', 'warum' => 'Mit Sitemap findet Google neue und geänderte Seiten schneller.', 'tun' => 'Eine Sitemap erzeugen und bei Google einreichen.'], 'info_en' => ['wie' => 'The check looks for a sitemap, a list of all pages, at the usual addresses and in robots.txt.', 'warum' => 'With a sitemap Google finds new and changed pages faster.', 'tun' => 'Create a sitemap and submit it to Google.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'canonical' => ['gruppe' => 'google', 'stufe' => 2, 'de' => 'Hauptadresse für Google festgelegt', 'en' => 'Main address set for Google', 'info_de' => ['wie' => 'Der Check sucht die „canonical“-Angabe, die Google sagt, welche Adresse die richtige für diese Seite ist.', 'warum' => 'Ohne sie kann Google dieselbe Seite mehrfach unter verschiedenen Adressen führen und sie dadurch schwächer bewerten.', 'tun' => 'Auf jeder Seite die eigene, endgültige Adresse eintragen.'], 'info_en' => ['wie' => 'The check looks for the “canonical” tag that tells Google which address is the right one for this page.', 'warum' => 'Without it Google may list the same page several times under different addresses and rank it lower.', 'tun' => 'Enter each page’s own final address.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'strukturdaten' => ['gruppe' => 'google', 'stufe' => 2, 'de' => 'Firmendaten für Google lesbar', 'en' => 'Business data readable for Google', 'info_de' => ['wie' => 'Der Check sucht strukturierte Daten, eine unsichtbare Beschreibung von Firma, Adresse und Angebot in Googles Format.', 'warum' => 'Damit kann Google Öffnungszeiten, Bewertungen oder Leistungen direkt in den Suchergebnissen zeigen.', 'tun' => 'Strukturierte Daten für Ihr Unternehmen ergänzen.'], 'info_en' => ['wie' => 'The check looks for structured data, an invisible description of business, address and offer in Google’s format.', 'warum' => 'This lets Google show opening hours, reviews or services directly in the search results.', 'tun' => 'Add structured data for your business.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'sprache' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Sprache der Seite angegeben', 'en' => 'Page language specified', 'info_de' => ['wie' => 'Der Check prüft, ob die Seite angibt, in welcher Sprache sie geschrieben ist (lang="de").', 'warum' => 'Das hilft Google, Übersetzungsdiensten und Vorlesehilfen, die Seite richtig zu verstehen und auszusprechen.', 'tun' => 'Die Sprachangabe im Seitenkopf ergänzen.'], 'info_en' => ['wie' => 'The check tests whether the page states the language it is written in (lang="de").', 'warum' => 'It helps Google, translation services and screen readers understand and pronounce the page correctly.', 'tun' => 'Add the language attribute to the page.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'alt' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Bilder sind beschrieben', 'en' => 'Images are described', 'info_de' => ['wie' => 'Der Check zählt, wie viele Bilder einen Alternativtext haben, also eine kurze Beschreibung für Menschen, die das Bild nicht sehen.', 'warum' => 'Google versteht Bilder nur über diesen Text, und für blinde Besucher ist er die einzige Information.', 'tun' => 'Jedem Bild eine kurze, passende Beschreibung geben.'], 'info_en' => ['wie' => 'The check counts how many images have alt text, a short description for people who cannot see the image.', 'warum' => 'Google understands images only through this text, and for blind visitors it is the only information.', 'tun' => 'Give each image a short, fitting description.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'ueberschriften' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Überschriften in sinnvoller Reihenfolge', 'en' => 'Headings in a sensible order', 'info_de' => ['wie' => 'Der Check prüft, ob Überschriftenebenen übersprungen werden, etwa von der Haupt- direkt zur dritten Ebene.', 'warum' => 'Eine saubere Gliederung hilft Google und Vorlesehilfen, den Aufbau zu verstehen.', 'tun' => 'Überschriften der Reihe nach ordnen.'], 'info_en' => ['wie' => 'The check tests whether heading levels are skipped, for example from the main heading straight to level three.', 'warum' => 'A clean outline helps Google and screen readers understand the structure.', 'tun' => 'Order the headings step by step.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'vorschau' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Schöne Vorschau beim Teilen', 'en' => 'Nice preview when shared', 'info_de' => ['wie' => 'Der Check sucht Titel und Vorschaubild für geteilte Links (Open Graph).', 'warum' => 'Wer Ihre Seite per WhatsApp oder LinkedIn teilt, sieht sonst nur einen nackten Link statt Bild und Titel.', 'tun' => 'Vorschaubild und Titel für das Teilen hinterlegen.'], 'info_en' => ['wie' => 'The check looks for a title and preview image for shared links (Open Graph).', 'warum' => 'Anyone sharing your site via WhatsApp or LinkedIn otherwise sees only a bare link instead of image and title.', 'tun' => 'Add a preview image and title for sharing.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'textmenge' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Genug Text auf der Startseite', 'en' => 'Enough text on the homepage', 'info_de' => ['wie' => 'Der Check zählt die Wörter auf der Startseite.', 'warum' => 'Google braucht Text, um zu verstehen, was Sie anbieten und wo. Ab etwa 300 Wörtern wird es deutlich besser.', 'tun' => 'Leistungen, Ort und Vorteile in eigenen Worten beschreiben.'], 'info_en' => ['wie' => 'The check counts the words on the homepage.', 'warum' => 'Google needs text to understand what you offer and where. From about 300 words it gets much better.', 'tun' => 'Describe services, location and benefits in your own words.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'titel_einmalig' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Jede Seite hat einen eigenen Titel', 'en' => 'Every page has its own title', 'info_de' => ['wie' => 'Der Check öffnet mehrere Unterseiten und vergleicht deren Seitentitel.', 'warum' => 'Tragen alle Seiten denselben Titel, kann Google sie nicht unterscheiden und zeigt oft die falsche.', 'tun' => 'Jeder Seite einen eigenen Titel mit ihrem Thema geben.'], 'info_en' => ['wie' => 'The check opens several subpages and compares their page titles.', 'warum' => 'If all pages share the same title, Google cannot tell them apart and often shows the wrong one.', 'tun' => 'Give each page its own title with its topic.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'robots_txt' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Hinweisdatei für Suchmaschinen', 'en' => 'Guidance file for search engines', 'info_de' => ['wie' => 'Der Check prüft, ob es die Datei „robots.txt“ gibt.', 'warum' => 'Sie sagt Suchmaschinen, was sie lesen dürfen, und verweist auf die Sitemap.', 'tun' => 'Eine einfache robots.txt mit Verweis auf die Sitemap anlegen.'], 'info_en' => ['wie' => 'The check tests whether the file “robots.txt” exists.', 'warum' => 'It tells search engines what they may read and points to the sitemap.', 'tun' => 'Create a simple robots.txt pointing to the sitemap.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'sitemap_robots' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Sitemap in der Hinweisdatei genannt', 'en' => 'Sitemap named in the guidance file', 'info_de' => ['wie' => 'Der Check schaut, ob die robots.txt auf die Sitemap verweist.', 'warum' => 'So finden alle Suchmaschinen das Seitenverzeichnis, nicht nur Google.', 'tun' => 'In die robots.txt eine Zeile mit „Sitemap“ und der Adresse Ihrer Sitemap schreiben.'], 'info_en' => ['wie' => 'The check tests whether robots.txt points to the sitemap.', 'warum' => 'This lets all search engines find the page list, not just Google.', 'tun' => 'Add a line with “Sitemap” and the address of your sitemap to robots.txt.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'sprachversionen' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Sprachversionen sind verknüpft', 'en' => 'Language versions are linked', 'info_de' => ['wie' => 'Gibt es Ihre Seite in mehreren Sprachen, sucht der Check die Angaben „hreflang“, die die Versionen miteinander verbinden.', 'warum' => 'Damit zeigt Google jedem Besucher die passende Sprache.', 'tun' => 'Die Sprachversionen gegenseitig verknüpfen.'], 'info_en' => ['wie' => 'If your site exists in several languages, the check looks for “hreflang” tags that link the versions.', 'warum' => 'This lets Google show every visitor the right language.', 'tun' => 'Link the language versions to each other.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'lokal' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Ort ist auf der Startseite erkennbar', 'en' => 'Location visible on the homepage', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite eine Postleitzahl oder eine Ortsangabe.', 'warum' => 'Wer „in meiner Nähe“ sucht, findet Sie bei Google nur, wenn der Ort auf der Seite steht.', 'tun' => 'Ort, Einzugsgebiet und Anschrift auf der Startseite nennen.'], 'info_en' => ['wie' => 'The check looks for a postcode or a location on the homepage.', 'warum' => 'People searching “near me” only find you on Google if your location is on the page.', 'tun' => 'Name your town, service area and address on the homepage.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'strukturdaten_firma' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Unternehmen bei Google eindeutig beschrieben', 'en' => 'Business clearly described for Google', 'info_de' => ['wie' => 'In den strukturierten Daten sucht der Check einen Eintrag als Firma oder lokales Geschäft.', 'warum' => 'So verknüpft Google Ihre Website leichter mit Ihrem Google-Unternehmensprofil und Ihren Bewertungen.', 'tun' => 'Den Eintrag „LocalBusiness“ oder „Organization“ ergänzen.'], 'info_en' => ['wie' => 'In the structured data the check looks for an entry as an organisation or local business.', 'warum' => 'This helps Google connect your website with your Google Business Profile and reviews.', 'tun' => 'Add a “LocalBusiness” or “Organization” entry.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'linktexte' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Links sagen, wohin sie führen', 'en' => 'Links say where they lead', 'info_de' => ['wie' => 'Der Check zählt Links mit Texten wie „hier klicken“ oder „mehr“ ohne weiteren Zusammenhang.', 'warum' => 'Google und Vorlesehilfen verstehen solche Links nicht. Ein klarer Linktext hilft beiden.', 'tun' => 'Linktexte so formulieren, dass das Ziel erkennbar ist.'], 'info_en' => ['wie' => 'The check counts links with texts like “click here” or “more” without further context.', 'warum' => 'Google and screen readers do not understand such links. Clear link text helps both.', 'tun' => 'Phrase link texts so the destination is clear.'], 'leistung' => 'seo', 'leistung_de' => 'Das erledige ich bei der Google-Optimierung, beim Neubau oder in der Betreuung.', 'leistung_en' => 'I handle this as part of Google optimisation, with a new build or in website maintenance.', 'leistung_name_de' => 'Google-Optimierung', 'leistung_name_en' => 'Google optimisation'],
    'unterseiten_offen' => ['gruppe' => 'google', 'stufe' => 3, 'de' => 'Unterseiten nicht versehentlich gesperrt', 'en' => 'Subpages not blocked by mistake', 'info_de' => ['wie' => 'Der Check öffnet mehrere Unterseiten (ohne Impressum und Datenschutz) und sucht dort eine Sperre für Suchmaschinen.', 'warum' => 'Gesperrte Unterseiten tauchen bei Google nicht auf, auch wenn sie wichtig sind.', 'tun' => 'Die Sperre auf den betroffenen Seiten entfernen.'], 'info_en' => ['wie' => 'The check opens several subpages (excluding legal pages) and looks for a search engine block there.', 'warum' => 'Blocked subpages do not appear on Google even if they matter.', 'tun' => 'Remove the block on the affected pages.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'tempo' => ['gruppe' => 'tempo', 'stufe' => 2, 'de' => 'Server antwortet schnell', 'en' => 'Server responds quickly', 'info_de' => ['wie' => 'Der Check misst, wie lange Ihr Server bis zur ersten Antwort braucht. Gut ist unter 0,8 Sekunden.', 'warum' => 'Jede Sekunde Wartezeit kostet Besucher. Langsame Antworten deuten auf schwaches Hosting oder fehlenden Zwischenspeicher hin.', 'tun' => 'Zwischenspeicher (Cache) einschalten oder schnelleres Hosting wählen.'], 'info_en' => ['wie' => 'The check measures how long your server takes to send the first response. Under 0.8 seconds is good.', 'warum' => 'Every second of waiting costs visitors. Slow responses point to weak hosting or a missing cache.', 'tun' => 'Switch on caching or choose faster hosting.'], 'leistung' => 'hoster', 'leistung_de' => 'Das kläre ich mit Ihrem Hoster oder ziehe die Website auf ein schnelleres Hosting um.', 'leistung_en' => 'I sort this out with your host or move the site to faster hosting.', 'leistung_name_de' => 'Hosting und Server', 'leistung_name_en' => 'Hosting and server'],
    'ladezeit' => ['gruppe' => 'tempo', 'stufe' => 2, 'de' => 'Startseite ist schnell geladen', 'en' => 'Homepage loads quickly', 'info_de' => ['wie' => 'Der Check misst, wie lange es dauert, bis die Startseite vollständig vom Server übertragen ist. Gut ist unter 2,5 Sekunden.', 'warum' => 'Lädt die Seite länger als drei Sekunden, verlässt ein großer Teil der Besucher sie wieder.', 'tun' => 'Seite verschlanken, Cache und Komprimierung einschalten.'], 'info_en' => ['wie' => 'The check measures how long it takes for the homepage to be fully transferred from the server. Under 2.5 seconds is good.', 'warum' => 'If the page takes more than three seconds, a large share of visitors leave.', 'tun' => 'Slim down the page and switch on caching and compression.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'komprimierung' => ['gruppe' => 'tempo', 'stufe' => 2, 'de' => 'Daten werden gepackt übertragen', 'en' => 'Data is sent compressed', 'info_de' => ['wie' => 'Der Check prüft, ob Ihr Server die Seite gepackt (gzip oder Brotli) schickt.', 'warum' => 'Gepackt ist die Seite oft 70 Prozent kleiner und dadurch deutlich schneller.', 'tun' => 'Komprimierung beim Hoster einschalten, meist ein Schalter.'], 'info_en' => ['wie' => 'The check tests whether your server sends the page compressed (gzip or Brotli).', 'warum' => 'Compressed, the page is often 70 percent smaller and much faster.', 'tun' => 'Switch on compression at your host, usually one switch.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'groesse' => ['gruppe' => 'tempo', 'stufe' => 2, 'de' => 'Schlanke Startseite', 'en' => 'Lean homepage', 'info_de' => ['wie' => 'Der Check misst die Größe der Startseite und zählt eingebundene Skripte, Stile und Bilder.', 'warum' => 'Zu viele Dateien machen die Seite auf dem Handy träge, besonders bei schlechtem Empfang.', 'tun' => 'Unnötige Erweiterungen entfernen und Dateien zusammenfassen.'], 'info_en' => ['wie' => 'The check measures the homepage size and counts embedded scripts, styles and images.', 'warum' => 'Too many files make the site sluggish on phones, especially with poor reception.', 'tun' => 'Remove unnecessary plugins and combine files.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'cache' => ['gruppe' => 'tempo', 'stufe' => 3, 'de' => 'Dateien werden zwischengespeichert', 'en' => 'Files are cached', 'info_de' => ['wie' => 'Der Check prüft bei einer Ihrer Dateien (z. B. dem Stylesheet), ob der Browser sie speichern darf.', 'warum' => 'Wiederkehrende Besucher laden die Seite dann deutlich schneller.', 'tun' => 'Zwischenspeicher-Regeln in der Server-Einstellung ergänzen.'], 'info_en' => ['wie' => 'The check tests one of your files (e.g. the stylesheet) to see whether the browser may store it.', 'warum' => 'Returning visitors then load the site much faster.', 'tun' => 'Add caching rules to the server settings.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'http2' => ['gruppe' => 'tempo', 'stufe' => 3, 'de' => 'Modernes Übertragungsverfahren', 'en' => 'Modern transfer method', 'info_de' => ['wie' => 'Der Check prüft, ob Ihr Server HTTP/2 oder neuer verwendet.', 'warum' => 'Damit lädt der Browser viele Dateien gleichzeitig statt nacheinander.', 'tun' => 'HTTP/2 beim Hoster einschalten.'], 'info_en' => ['wie' => 'The check tests whether your server uses HTTP/2 or newer.', 'warum' => 'It lets the browser load many files at once instead of one by one.', 'tun' => 'Switch on HTTP/2 at your host.'], 'leistung' => 'hoster', 'leistung_de' => 'Das kläre ich mit Ihrem Hoster oder ziehe die Website auf ein schnelleres Hosting um.', 'leistung_en' => 'I sort this out with your host or move the site to faster hosting.', 'leistung_name_de' => 'Hosting und Server', 'leistung_name_en' => 'Hosting and server'],
    'blockierend' => ['gruppe' => 'tempo', 'stufe' => 3, 'de' => 'Skripte bremsen den Seitenaufbau nicht', 'en' => 'Scripts do not slow page building', 'info_de' => ['wie' => 'Der Check zählt Skripte im Seitenkopf, die ohne „async“ oder „defer“ geladen werden und den Aufbau anhalten.', 'warum' => 'Solange solche Skripte laden, sehen Besucher eine leere Seite.', 'tun' => 'Skripte verzögert laden lassen.'], 'info_en' => ['wie' => 'The check counts scripts in the page head that load without “async” or “defer” and pause rendering.', 'warum' => 'While such scripts load, visitors see a blank page.', 'tun' => 'Make scripts load deferred.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'stylesheets' => ['gruppe' => 'tempo', 'stufe' => 3, 'de' => 'Wenige Stil-Dateien', 'en' => 'Few style files', 'info_de' => ['wie' => 'Der Check zählt die eingebundenen Stylesheets (Gestaltungsdateien).', 'warum' => 'Jede zusätzliche Datei ist eine weitere Anfrage, bevor die Seite angezeigt werden kann.', 'tun' => 'Stylesheets zusammenfassen.'], 'info_en' => ['wie' => 'The check counts the embedded stylesheets (design files).', 'warum' => 'Every additional file is one more request before the page can be shown.', 'tun' => 'Combine the stylesheets.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'fremde_skripte' => ['gruppe' => 'tempo', 'stufe' => 3, 'de' => 'Wenige fremde Skripte', 'en' => 'Few third-party scripts', 'info_de' => ['wie' => 'Der Check zählt, von wie vielen fremden Adressen Skripte geladen werden.', 'warum' => 'Jeder fremde Dienst kostet Zeit und kann die Seite ausbremsen, wenn er langsam ist.', 'tun' => 'Nicht benötigte Dienste entfernen.'], 'info_en' => ['wie' => 'The check counts how many foreign addresses scripts are loaded from.', 'warum' => 'Every third-party service costs time and can slow the site if it is slow itself.', 'tun' => 'Remove services you do not need.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'unterseiten_tempo' => ['gruppe' => 'tempo', 'stufe' => 3, 'de' => 'Unterseiten antworten schnell', 'en' => 'Subpages respond quickly', 'info_de' => ['wie' => 'Der Check misst, wie schnell die geprüften Unterseiten vom Server kommen. Gut ist im Schnitt unter einer Sekunde.', 'warum' => 'Auch Besucher, die über Google direkt auf einer Unterseite landen, sollen nicht warten.', 'tun' => 'Cache und Hosting prüfen, große Seiten verschlanken.'], 'info_en' => ['wie' => 'The check measures how quickly the checked subpages arrive from the server. Under one second on average is good.', 'warum' => 'Visitors landing directly on a subpage via Google should not have to wait either.', 'tun' => 'Check caching and hosting, slim down large pages.'], 'leistung' => 'hoster', 'leistung_de' => 'Das kläre ich mit Ihrem Hoster oder ziehe die Website auf ein schnelleres Hosting um.', 'leistung_en' => 'I sort this out with your host or move the site to faster hosting.', 'leistung_name_de' => 'Hosting und Server', 'leistung_name_en' => 'Hosting and server'],
    'kontakt' => ['gruppe' => 'kontakt', 'stufe' => 1, 'de' => 'Kontakt direkt von der Startseite', 'en' => 'Contact directly from the homepage', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite Telefon, E-Mail, Formular oder einen Link zur Kontaktseite.', 'warum' => 'Wer nicht sofort sieht, wie er Sie erreicht, geht zur Konkurrenz.', 'tun' => 'Telefon und Kontakt gut sichtbar im Kopf und in der Fußzeile zeigen.'], 'info_en' => ['wie' => 'The check looks on the homepage for phone, email, a form or a link to the contact page.', 'warum' => 'Anyone who cannot see right away how to reach you goes to the competition.', 'tun' => 'Show phone and contact clearly in the header and footer.'], 'leistung' => 'neubau', 'leistung_de' => 'Bei einer neuen Website in 7 Tagen ist das von Anfang an erledigt.', 'leistung_en' => 'With a new website in 7 days, this is done from the start.', 'leistung_name_de' => 'Neue Website in 7 Tagen', 'leistung_name_en' => 'New website in 7 days'],
    'telefon' => ['gruppe' => 'kontakt', 'stufe' => 2, 'de' => 'Telefonnummer zum Antippen', 'en' => 'Tap-to-call phone number', 'info_de' => ['wie' => 'Der Check sucht eine Telefonnummer, die als Link hinterlegt ist (tel:).', 'warum' => 'Auf dem Handy ruft ein Tipp direkt an. Das bringt messbar mehr Anfragen.', 'tun' => 'Die Telefonnummer als Anruf-Link setzen.'], 'info_en' => ['wie' => 'The check looks for a phone number set as a link (tel:).', 'warum' => 'On a phone, one tap calls directly. This measurably brings more inquiries.', 'tun' => 'Turn the phone number into a call link.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'handlung' => ['gruppe' => 'kontakt', 'stufe' => 3, 'de' => 'Klarer nächster Schritt', 'en' => 'Clear next step', 'info_de' => ['wie' => 'Der Check sucht Knöpfe oder Links wie „Termin buchen“, „Angebot anfordern“ oder „Jetzt anfragen“.', 'warum' => 'Besucher brauchen eine klare Aufforderung, sonst lesen sie und gehen wieder.', 'tun' => 'Einen gut sichtbaren Knopf mit dem wichtigsten Schritt einbauen.'], 'info_en' => ['wie' => 'The check looks for buttons or links like “Book an appointment”, “Request a quote” or “Enquire now”.', 'warum' => 'Visitors need a clear call to action, otherwise they read and leave.', 'tun' => 'Add a clearly visible button for the most important step.'], 'leistung' => 'neubau', 'leistung_de' => 'Bei einer neuen Website in 7 Tagen ist das von Anfang an erledigt.', 'leistung_en' => 'With a new website in 7 days, this is done from the start.', 'leistung_name_de' => 'Neue Website in 7 Tagen', 'leistung_name_en' => 'New website in 7 days'],
    'email_link' => ['gruppe' => 'kontakt', 'stufe' => 3, 'de' => 'E-Mail-Adresse anklickbar', 'en' => 'Clickable email address', 'info_de' => ['wie' => 'Der Check sucht eine E-Mail-Adresse, die als Link hinterlegt ist (mailto:), auf der Startseite oder im Impressum.', 'warum' => 'Ein Klick öffnet das E-Mail-Programm, abtippen entfällt.', 'tun' => 'Die E-Mail-Adresse verlinken.'], 'info_en' => ['wie' => 'The check looks for an email address set as a link (mailto:), on the homepage or in the legal notice.', 'warum' => 'One click opens the email app, no retyping needed.', 'tun' => 'Link the email address.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'zeiten' => ['gruppe' => 'kontakt', 'stufe' => 3, 'de' => 'Erreichbarkeit oder Öffnungszeiten genannt', 'en' => 'Opening hours or availability shown', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite Öffnungs- oder Erreichbarkeitszeiten.', 'warum' => 'Besucher wissen dann, wann sie Sie erreichen, und rufen nicht ins Leere an.', 'tun' => 'Zeiten auf der Startseite und im Google-Profil angeben.'], 'info_en' => ['wie' => 'The check looks on the homepage for opening hours or availability.', 'warum' => 'Visitors then know when they can reach you and do not call in vain.', 'tun' => 'Show your hours on the homepage and in your Google profile.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'vertrauen' => ['gruppe' => 'kontakt', 'stufe' => 3, 'de' => 'Bewertungen oder Referenzen sichtbar', 'en' => 'Reviews or references visible', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite Hinweise auf Bewertungen, Kundenstimmen oder Referenzen.', 'warum' => 'Echte Erfahrungen anderer Kunden sind eines der stärksten Argumente für eine Anfrage.', 'tun' => 'Echte Kundenstimmen oder Google-Bewertungen einbinden.'], 'info_en' => ['wie' => 'The check looks on the homepage for reviews, testimonials or references.', 'warum' => 'Real experiences of other customers are one of the strongest reasons to get in touch.', 'tun' => 'Show real testimonials or Google reviews.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'ueber_uns' => ['gruppe' => 'kontakt', 'stufe' => 3, 'de' => 'Menschen hinter dem Angebot', 'en' => 'People behind the offer', 'info_de' => ['wie' => 'Der Check sucht einen Link zu „Über uns“, „Team“ oder „Über mich“.', 'warum' => 'Gerade bei Dienstleistungen wollen Kunden wissen, mit wem sie es zu tun haben.', 'tun' => 'Eine kurze Seite mit Foto und Vorstellung anlegen.'], 'info_en' => ['wie' => 'The check looks for a link to “About us”, “Team” or “About me”.', 'warum' => 'Especially for services, customers want to know who they are dealing with.', 'tun' => 'Create a short page with a photo and introduction.'], 'leistung' => 'neubau', 'leistung_de' => 'Bei einer neuen Website in 7 Tagen ist das von Anfang an erledigt.', 'leistung_en' => 'With a new website in 7 days, this is done from the start.', 'leistung_name_de' => 'Neue Website in 7 Tagen', 'leistung_name_en' => 'New website in 7 days'],
    'gepflegt' => ['gruppe' => 'kontakt', 'stufe' => 3, 'de' => 'Website wirkt gepflegt', 'en' => 'Website looks maintained', 'info_de' => ['wie' => 'Der Check sucht in der Fußzeile eine aktuelle Jahreszahl (z. B. „© 2026“) und prüft, ob sie veraltet ist.', 'warum' => 'Eine alte Jahreszahl lässt Besucher zweifeln, ob es das Unternehmen noch gibt.', 'tun' => 'Die Jahreszahl automatisch aktualisieren lassen.'], 'info_en' => ['wie' => 'The check looks in the footer for a current year (e.g. “© 2026”) and checks whether it is outdated.', 'warum' => 'An old year makes visitors wonder whether the business still exists.', 'tun' => 'Have the year update automatically.'], 'leistung' => 'betreuung', 'leistung_de' => 'Das übernehme ich in der Website-Betreuung ab 29 € im Monat.', 'leistung_en' => 'I take care of this in website maintenance from €29 per month.', 'leistung_name_de' => 'Website-Betreuung ab 29 € im Monat', 'leistung_name_en' => 'Website maintenance from €29 per month'],
    'formular' => ['gruppe' => 'anbindungen', 'stufe' => 2, 'de' => 'Kontaktformular vorhanden', 'en' => 'Contact form available', 'info_de' => ['wie' => 'Der Check sucht auf der Startseite und der Kontaktseite ein Formular mit Feldern für E-Mail und Nachricht.', 'warum' => 'Viele Menschen schreiben lieber, als anzurufen, vor allem abends und am Wochenende.', 'tun' => 'Ein schlankes Formular einbauen, das Anfragen sofort bestätigt.'], 'info_en' => ['wie' => 'The check looks on the homepage and contact page for a form with fields for email and message.', 'warum' => 'Many people prefer writing to calling, especially in the evening and at weekends.', 'tun' => 'Add a lean form that confirms inquiries instantly.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'karte' => ['gruppe' => 'anbindungen', 'stufe' => 2, 'de' => 'Karte datenschutzfreundlich eingebunden', 'en' => 'Map embedded in a privacy-friendly way', 'info_de' => ['wie' => 'Der Check prüft, ob eine Google-Karte schon beim Aufruf geladen wird oder erst nach einem Klick.', 'warum' => 'Eine sofort geladene Google-Karte schickt die IP-Adresse an Google, ohne Zustimmung ist das unzulässig.', 'tun' => 'Die Karte erst nach Klick laden oder ein Kartenbild mit Link verwenden.'], 'info_en' => ['wie' => 'The check tests whether a Google map loads on arrival or only after a click.', 'warum' => 'A map loaded right away sends the IP address to Google, which is not allowed without consent.', 'tun' => 'Load the map only after a click or use a map image with a link.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'formular_schutz' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Formular gegen Spam geschützt', 'en' => 'Form protected against spam', 'info_de' => ['wie' => 'Gibt es ein Formular, sucht der Check einen unsichtbaren Spam-Schutz oder ein Prüffeld.', 'warum' => 'Ohne Schutz füllen Programme das Formular massenhaft aus, echte Anfragen gehen unter.', 'tun' => 'Einen unsichtbaren Spam-Schutz ergänzen.'], 'info_en' => ['wie' => 'If there is a form, the check looks for invisible spam protection or a verification field.', 'warum' => 'Without protection, bots fill in the form en masse and real inquiries get lost.', 'tun' => 'Add invisible spam protection.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'buchung' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Termine online buchbar', 'en' => 'Appointments bookable online', 'info_de' => ['wie' => 'Der Check sucht eine Online-Terminbuchung, etwa einen Buchungskalender oder einen Link „Termin buchen“.', 'warum' => 'Kunden buchen dann auch abends, ohne anzurufen. Das spart Telefonate und füllt den Kalender.', 'tun' => 'Eine Terminbuchung anbinden, die mit Ihrem Kalender abgeglichen wird.'], 'info_en' => ['wie' => 'The check looks for online booking, such as a booking calendar or a “book an appointment” link.', 'warum' => 'Customers can then book in the evening without calling. That saves phone calls and fills your calendar.', 'tun' => 'Connect online booking that syncs with your calendar.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'messenger' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Erreichbar per WhatsApp oder Messenger', 'en' => 'Reachable via WhatsApp or messenger', 'info_de' => ['wie' => 'Der Check sucht einen Link zu WhatsApp, Telegram oder Signal.', 'warum' => 'Für viele Kunden ist eine kurze Nachricht der einfachste Weg, Kontakt aufzunehmen.', 'tun' => 'Einen Messenger-Knopf einbauen, auf Wunsch mit automatischer Antwort.'], 'info_en' => ['wie' => 'The check looks for a link to WhatsApp, Telegram or Signal.', 'warum' => 'For many customers a short message is the easiest way to get in touch.', 'tun' => 'Add a messenger button, optionally with an automatic reply.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'video' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Videos datenschutzfreundlich eingebunden', 'en' => 'Videos embedded in a privacy-friendly way', 'info_de' => ['wie' => 'Der Check prüft, ob YouTube- oder Vimeo-Videos schon beim Aufruf geladen werden.', 'warum' => 'Eingebettete Videos übertragen Daten an den Anbieter, bevor jemand auf „Abspielen“ drückt.', 'tun' => 'Videos erst nach Klick laden oder den datensparsamen Modus nutzen.'], 'info_en' => ['wie' => 'The check tests whether YouTube or Vimeo videos load on arrival.', 'warum' => 'Embedded videos send data to the provider before anyone presses “play”.', 'tun' => 'Load videos only after a click or use the privacy-enhanced mode.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'social' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Social-Media-Profile verlinkt', 'en' => 'Social media profiles linked', 'info_de' => ['wie' => 'Der Check sucht Links zu Instagram, Facebook, LinkedIn, TikTok, YouTube oder Xing.', 'warum' => 'Verlinkte Profile zeigen, dass Ihr Unternehmen aktiv ist, und helfen Google, Sie zuzuordnen.', 'tun' => 'Die Profile in der Fußzeile verlinken.'], 'info_en' => ['wie' => 'The check looks for links to Instagram, Facebook, LinkedIn, TikTok, YouTube or Xing.', 'warum' => 'Linked profiles show that your business is active and help Google identify you.', 'tun' => 'Link the profiles in the footer.'], 'leistung' => 'reparatur', 'leistung_de' => 'Das behebe ich als einmalige Reparatur, meist in weniger als einer Stunde.', 'leistung_en' => 'I fix this as a one-off repair, usually in under an hour.', 'leistung_name_de' => 'Einmalige Reparatur', 'leistung_name_en' => 'One-off repair'],
    'bewertungsprofil' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Google-Profil oder Bewertungen verlinkt', 'en' => 'Google profile or reviews linked', 'info_de' => ['wie' => 'Der Check sucht Links zu Ihrem Google-Unternehmensprofil oder zu Bewertungsportalen.', 'warum' => 'Zufriedene Kunden finden so leichter den Weg zur Bewertung. Mehr Bewertungen bringen mehr Anfragen.', 'tun' => 'Einen Bewertungslink einbauen und nach jedem Auftrag automatisch um eine Bewertung bitten.'], 'info_en' => ['wie' => 'The check looks for links to your Google Business Profile or review sites.', 'warum' => 'Happy customers can find the way to leave a review more easily. More reviews bring more inquiries.', 'tun' => 'Add a review link and automatically ask for a review after each job.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'newsletter' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Newsletter mit Bestätigung', 'en' => 'Newsletter with confirmation', 'info_de' => ['wie' => 'Findet der Check eine Newsletter-Anmeldung, sucht er den Hinweis auf eine Bestätigung per E-Mail (Double-Opt-in).', 'warum' => 'Ohne Bestätigung können Fremde beliebige Adressen eintragen. Das ist rechtlich riskant.', 'tun' => 'Die Anmeldung mit Bestätigungs-E-Mail einrichten.'], 'info_en' => ['wie' => 'If the check finds a newsletter sign-up, it looks for a note about email confirmation (double opt-in).', 'warum' => 'Without confirmation anyone can sign up any address. That is legally risky.', 'tun' => 'Set up sign-up with a confirmation email.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'chat' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Chat-Fenster laden erst nach Zustimmung', 'en' => 'Chat widgets load only after consent', 'info_de' => ['wie' => 'Der Check sucht eingebaute Chat-Dienste (z. B. Tawk, Tidio, Intercom), die schon beim Aufruf geladen werden.', 'warum' => 'Solche Dienste übertragen sofort Daten an den Anbieter und bremsen die Seite.', 'tun' => 'Den Chat erst nach Klick laden oder durch eine eigene Lösung ersetzen.'], 'info_en' => ['wie' => 'The check looks for built-in chat services (e.g. Tawk, Tidio, Intercom) that load on arrival.', 'warum' => 'Such services send data to the provider right away and slow the site.', 'tun' => 'Load the chat only after a click or replace it with your own solution.'], 'leistung' => 'automatik', 'leistung_de' => 'Das übernimmt die Anfrage-Automatik für Sie.', 'leistung_en' => 'The inquiry automation takes care of this for you.', 'leistung_name_de' => 'Anfrage-Automatik', 'leistung_name_en' => 'Inquiry automation'],
    'shop_recht' => ['gruppe' => 'anbindungen', 'stufe' => 3, 'de' => 'Shop mit AGB und Widerruf', 'en' => 'Shop with terms and cancellation policy', 'info_de' => ['wie' => 'Erkennt der Check einen Shop oder Zahlungsanbieter, sucht er Links zu AGB und Widerrufsbelehrung.', 'warum' => 'Fehlen sie, ist der Kauf angreifbar und Abmahnungen sind wahrscheinlich.', 'tun' => 'AGB und Widerrufsbelehrung ergänzen und im Bestellablauf verlinken.'], 'info_en' => ['wie' => 'If the check detects a shop or payment provider, it looks for links to terms and the cancellation policy.', 'warum' => 'If they are missing, purchases can be challenged and legal warnings are likely.', 'tun' => 'Add terms and the cancellation policy and link them in the checkout.'], 'leistung' => 'recht', 'leistung_de' => 'Die technische Umsetzung übernehme ich. Den Inhalt der Rechtstexte prüft am besten ein Rechtstext-Dienst oder eine Anwältin.', 'leistung_en' => 'I handle the technical side. The content of legal texts is best checked by a legal-text service or a lawyer.', 'leistung_name_de' => 'Rechtstexte technisch umsetzen', 'leistung_name_en' => 'Implementing legal texts'],
    'spf' => ['gruppe' => 'email', 'stufe' => 2, 'de' => 'Absender Ihrer E-Mails geschützt', 'en' => 'Your email sender is protected', 'info_de' => ['wie' => 'Der Check sucht in Ihrer Domain den SPF-Eintrag, der festlegt, welche Server in Ihrem Namen E-Mails senden dürfen.', 'warum' => 'Ohne SPF landen Ihre E-Mails öfter im Spam, und Betrüger können leichter in Ihrem Namen schreiben.', 'tun' => 'Den SPF-Eintrag Ihres E-Mail-Anbieters in die Domain eintragen.'], 'info_en' => ['wie' => 'The check looks in your domain for the SPF record that defines which servers may send email in your name.', 'warum' => 'Without SPF your emails land in spam more often and fraudsters can write in your name more easily.', 'tun' => 'Add your email provider’s SPF record to the domain.'], 'leistung' => 'mail', 'leistung_de' => 'Das richte ich gemeinsam mit Ihnen bei Ihrem E-Mail-Anbieter ein, über die Einträge in Ihrer Domain.', 'leistung_en' => 'I set this up with you at your email provider, using the records in your domain.', 'leistung_name_de' => 'E-Mail-Einrichtung', 'leistung_name_en' => 'Email setup'],
    'dmarc' => ['gruppe' => 'email', 'stufe' => 2, 'de' => 'Schutz vor gefälschten E-Mails', 'en' => 'Protection against fake emails', 'info_de' => ['wie' => 'Der Check sucht den DMARC-Eintrag, der Empfängern sagt, was mit gefälschten E-Mails von Ihrer Domain passieren soll.', 'warum' => 'Gmail und Yahoo verlangen ihn zunehmend. Fehlt er, kommen Ihre E-Mails schlechter an.', 'tun' => 'Einen DMARC-Eintrag anlegen.'], 'info_en' => ['wie' => 'The check looks for the DMARC record that tells recipients what to do with fake emails from your domain.', 'warum' => 'Gmail and Yahoo increasingly require it. Without it your emails are delivered less reliably.', 'tun' => 'Create a DMARC record.'], 'leistung' => 'mail', 'leistung_de' => 'Das richte ich gemeinsam mit Ihnen bei Ihrem E-Mail-Anbieter ein, über die Einträge in Ihrer Domain.', 'leistung_en' => 'I set this up with you at your email provider, using the records in your domain.', 'leistung_name_de' => 'E-Mail-Einrichtung', 'leistung_name_en' => 'Email setup'],
    'mx' => ['gruppe' => 'email', 'stufe' => 3, 'de' => 'Domain kann E-Mails empfangen', 'en' => 'Domain can receive email', 'info_de' => ['wie' => 'Der Check prüft, ob Ihre Domain einen Posteingangs-Server (MX-Eintrag) hat.', 'warum' => 'Ohne ihn kommen E-Mails an Adressen Ihrer Domain nicht an.', 'tun' => 'Beim Hoster ein Postfach einrichten oder den MX-Eintrag setzen.'], 'info_en' => ['wie' => 'The check tests whether your domain has an incoming mail server (MX record).', 'warum' => 'Without it, emails to addresses at your domain do not arrive.', 'tun' => 'Set up a mailbox at your host or add the MX record.'], 'leistung' => 'mail', 'leistung_de' => 'Das richte ich gemeinsam mit Ihnen bei Ihrem E-Mail-Anbieter ein, über die Einträge in Ihrer Domain.', 'leistung_en' => 'I set this up with you at your email provider, using the records in your domain.', 'leistung_name_de' => 'E-Mail-Einrichtung', 'leistung_name_en' => 'Email setup'],
    'spf_streng' => ['gruppe' => 'email', 'stufe' => 3, 'de' => 'Absenderschutz ist streng genug', 'en' => 'Sender protection is strict enough', 'info_de' => ['wie' => 'Der Check prüft, ob Ihr SPF-Eintrag fremde Server abweist (Ende „-all“ oder „~all“) statt alle zu erlauben.', 'warum' => 'Ein zu offener Eintrag schützt praktisch nicht.', 'tun' => 'Den Eintrag mit „~all“ oder „-all“ abschließen.'], 'info_en' => ['wie' => 'The check tests whether your SPF record rejects foreign servers (ending “-all” or “~all”) instead of allowing all.', 'warum' => 'A record that is too open offers practically no protection.', 'tun' => 'End the record with “~all” or “-all”.'], 'leistung' => 'mail', 'leistung_de' => 'Das richte ich gemeinsam mit Ihnen bei Ihrem E-Mail-Anbieter ein, über die Einträge in Ihrer Domain.', 'leistung_en' => 'I set this up with you at your email provider, using the records in your domain.', 'leistung_name_de' => 'E-Mail-Einrichtung', 'leistung_name_en' => 'Email setup'],
    'dmarc_streng' => ['gruppe' => 'email', 'stufe' => 3, 'de' => 'Gefälschte E-Mails werden aussortiert', 'en' => 'Fake emails are filtered out', 'info_de' => ['wie' => 'Der Check prüft, ob Ihr DMARC-Eintrag gefälschte E-Mails in den Spam schickt oder ablehnt (quarantine oder reject).', 'warum' => 'Steht er nur auf „beobachten“ (none), kommen Fälschungen trotzdem an.', 'tun' => 'Nach einer Beobachtungszeit auf „quarantine“ oder „reject“ umstellen.'], 'info_en' => ['wie' => 'The check tests whether your DMARC record sends fake emails to spam or rejects them (quarantine or reject).', 'warum' => 'If it is only set to “observe” (none), fakes still get through.', 'tun' => 'After an observation period, switch to “quarantine” or “reject”.'], 'leistung' => 'mail', 'leistung_de' => 'Das richte ich gemeinsam mit Ihnen bei Ihrem E-Mail-Anbieter ein, über die Einträge in Ihrer Domain.', 'leistung_en' => 'I set this up with you at your email provider, using the records in your domain.', 'leistung_name_de' => 'E-Mail-Einrichtung', 'leistung_name_en' => 'Email setup'],
    'email_eigen' => ['gruppe' => 'email', 'stufe' => 3, 'de' => 'Kontakt-E-Mail auf der eigenen Domain', 'en' => 'Contact email on your own domain', 'info_de' => ['wie' => 'Der Check prüft, ob die angegebene E-Mail-Adresse zur Domain der Website gehört statt zu Gmail, Web.de oder ähnlichen.', 'warum' => 'Eine eigene Adresse wirkt professioneller und gehört Ihnen, auch wenn Sie den Anbieter wechseln.', 'tun' => 'Eine Adresse wie info@ihre-firma.de einrichten.'], 'info_en' => ['wie' => 'The check tests whether the email address shown belongs to the website’s domain rather than Gmail, Web.de or similar.', 'warum' => 'An address on your own domain looks more professional and stays yours even if you switch providers.', 'tun' => 'Set up an address like info@your-company.com.'], 'leistung' => 'mail', 'leistung_de' => 'Das richte ich gemeinsam mit Ihnen bei Ihrem E-Mail-Anbieter ein, über die Einträge in Ihrer Domain.', 'leistung_en' => 'I set this up with you at your email provider, using the records in your domain.', 'leistung_name_de' => 'E-Mail-Einrichtung', 'leistung_name_en' => 'Email setup'],
  ],
];
